Problem: Given regular pentagon $ABCDE,$ a circle can be drawn that is tangent to $\overline{DC}$ at $D$ and to $\overline{AB}$ at $A.$ In degrees, what is the measure of minor arc $AD$? [asy]import olympiad; import geometry; size(100); defaultpen(linewidth(0.8));
pair[] pentagon = new pair[5];
pentagon[0] = dir(36);
pentagon.cyclic=true;
for(int i = 1; i < 6; ++i){

pentagon[i] = dir(72*i + 36);

draw(pentagon[i - 1]--pentagon[i]);
}
dot("$C$",pentagon[0],NE);
dot("$D$",pentagon[1],N);
dot("$E$",pentagon[2],W);
dot("$A$",pentagon[3],S);
dot("$B$",pentagon[4],SE);
line x = line(pentagon[1],pentagon[1] + dir(-108));
line x2 = line(origin,pentagon[2]);
pair ccenter = coordinates(intersectionpoint(x,x2));
draw(Circle(ccenter,arclength(ccenter--pentagon[1])));
[/asy]

